"""Shipped-orders reconciliation against the local order service.

Usage:
  python3 -I recon.py fetch-orders    <run_dir>
  python3 -I recon.py fetch-customers <run_dir>
  python3 -I recon.py compute         <run_dir> <out_json>
"""
import datetime as dt
import email.utils
import http.client
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}
CUSTOMER_KEYS = {"id", "name", "region", "tier", "discount_pct"}


class Client:
    def __init__(self, run_dir):
        self.token = None
        self.log = open(os.path.join(run_dir, "events.jsonl"), "a")
        self.stats = Counter()

    def event(self, **kw):
        kw["t"] = time.time()
        self.log.write(json.dumps(kw) + "\n")
        self.log.flush()

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()
        except (urllib.error.URLError, ConnectionError, TimeoutError,
                http.client.HTTPException, OSError) as e:
            return None, None, repr(e).encode()

    @staticmethod
    def _json(body):
        try:
            return json.loads(body)
        except (ValueError, UnicodeDecodeError):
            return None

    @staticmethod
    def _retry_after(headers, data):
        v = headers.get("Retry-After") if headers is not None else None
        if v is not None:
            v = v.strip()
            try:
                return float(v)
            except ValueError:
                when = email.utils.parsedate_to_datetime(v)
                return max(0.0, (when - dt.datetime.now(dt.timezone.utc)).total_seconds())
        if isinstance(data, dict) and isinstance(data.get("retry_after"), (int, float)):
            return float(data["retry_after"])
        return None

    def _handle_failure(self, what, path, status, headers, body, attempt):
        """Log a failed exchange and sleep as appropriate. Returns 'retry' or 'reauth'."""
        data = self._json(body)
        ra = self._retry_after(headers, data)
        self.stats[(what, status)] += 1
        self.event(kind=what, path=path, status=status, retry_after=ra,
                   body=body[:400].decode("utf-8", "replace"))
        if status in (401, 403):
            return "reauth"
        if status == 429:
            if ra is None:
                raise RuntimeError(f"429 without a wait hint on {path}: {body!r}")
            time.sleep(ra)
            return "retry"
        # 5xx, connection errors, anything else transient: honour a hint if given,
        # otherwise back off gently.
        time.sleep(ra if ra is not None else min(0.25 * attempt, 3.0))
        return "retry"

    def refresh_token(self):
        for attempt in range(1, 101):
            status, headers, body = self._raw("POST", "/token", auth=False)
            data = self._json(body)
            if status == 200 and isinstance(data, dict) and isinstance(data.get("token"), str) and data["token"]:
                self.token = data["token"]
                self.stats["tokens_issued"] += 1
                self.event(kind="token", token=self.token)
                return
            if status == 200:  # 200 but unusable body
                status = "bad-200"
            self._handle_failure("token", "/token", status, headers, body, attempt)
        raise RuntimeError("could not obtain a token")

    def get(self, path, validate, allow_404=False, max_attempts=200):
        """GET an authenticated path until a response passes `validate`.

        A 404 is only accepted (returned as None) when allow_404 is set and it
        repeats on several spaced-out attempts, so a transient 404 is not
        mistaken for a missing record."""
        consecutive_404 = 0
        for attempt in range(1, max_attempts + 1):
            if self.token is None:
                self.refresh_token()
            status, headers, body = self._raw("GET", path, auth=True)
            self.stats["requests"] += 1
            if status == 200:
                data = self._json(body)
                problem = validate(data) if data is not None else "invalid JSON"
                if problem is None:
                    return data
                self.stats[("bad-200", path.split("?")[0].rsplit("/", 1)[0])] += 1
                self.event(kind="bad-200", path=path, problem=problem,
                           body=body[:400].decode("utf-8", "replace"))
                time.sleep(min(0.25 * attempt, 3.0))
                continue
            if status == 404 and allow_404:
                consecutive_404 += 1
                self.event(kind="get", path=path, status=404,
                           body=body[:400].decode("utf-8", "replace"))
                if consecutive_404 >= 4:
                    return None
                time.sleep(0.5 * consecutive_404)
                continue
            consecutive_404 = 0
            if self._handle_failure("get", path, status, headers, body, attempt) == "reauth":
                self.token = None
        raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")


def page_validator(expected_page):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = {"page", "total_pages", "items", "next"} - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["page"] != expected_page:
            return f"page field {d['page']!r} != requested {expected_page}"
        if not isinstance(d["items"], list):
            return "items is not a list"
        for it in d["items"]:
            if not isinstance(it, dict) or not ORDER_KEYS <= it.keys():
                return f"malformed item {it!r}"
        return None
    return validate


def customer_validator(cid):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = CUSTOMER_KEYS - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["id"] != cid:
            return f"id {d['id']!r} != requested {cid!r}"
        return None
    return validate


def page_number(path):
