    return int(m.group(1)) if m else None


def fetch_orders(run_dir):
    c = Client(run_dir)
    pages_dir = os.path.join(run_dir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    path, expected, totals, seq = "/orders?page=1", 1, set(), []
    while path is not None:
        n = page_number(path)
        if n != expected:
            raise RuntimeError(f"next link {path!r} is not page {expected}")
        d = c.get(path, page_validator(n))
        totals.add(d["total_pages"])
        with open(os.path.join(pages_dir, f"page_{n:03d}.json"), "w") as f:
            json.dump(d, f)
        seq.append((n, len(d["items"]), d["next"]))
        path, expected = d["next"], expected + 1
    summary = {
        "pages_fetched": len(seq),
        "total_pages_values": sorted(totals),
        "items_per_page": [s[1] for s in seq],
        "last_next": seq[-1][2],
        "stats": {str(k): v for k, v in c.stats.items()},
    }
    with open(os.path.join(run_dir, "orders_summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps(summary, indent=1))


def load_listing(run_dir):
    pages_dir = os.path.join(run_dir, "pages")
    names = sorted(os.listdir(pages_dir))
    listing = []
    for name in names:
        with open(os.path.join(pages_dir, name)) as f:
            d = json.load(f)
        for it in d["items"]:
            listing.append((d["page"], it))
    return listing


def parse_ts(s):
    t = dt.datetime.fromisoformat(s.replace("Z", "+00:00") if s.endswith("Z") else s)
    if t.tzinfo is None:
        raise ValueError(f"timestamp without offset: {s!r}")
    return t.astimezone(dt.timezone.utc)


START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)  # exclusive


def dedupe(listing):
    """First listing of each id wins; returns (orders, duplicates_skipped, conflicts)."""
    first, dups, conflicts = {}, 0, []
    for page, it in listing:
        if it["id"] in first:
            dups += 1
            if first[it["id"]][1] != it:
                conflicts.append((first[it["id"]], (page, it)))
        else:
            first[it["id"]] = (page, it)
    return {k: v[1] for k, v in first.items()}, dups, conflicts


def qualifying(orders):
    out = []
    for o in orders.values():
        if o["status"] != "shipped":
            continue
        if START <= parse_ts(o["placed_at"]) < END:
            out.append(o)
    return out


def fetch_customers(run_dir):
    orders, _, _ = dedupe(load_listing(run_dir))
    needed = sorted({o["customer_id"] for o in qualifying(orders)})
    cache_path = os.path.join(run_dir, "customers.json")
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path) as f:
            cache = json.load(f)
    c = Client(run_dir)
    for cid in needed:
        if cid in cache:
            continue
        cache[cid] = c.get(f"/customers/{urllib.parse.quote(cid, safe='')}",
                           customer_validator(cid), allow_404=True)
        with open(cache_path, "w") as f:
            json.dump(cache, f, indent=1, sort_keys=True)
    print(json.dumps({"customers_needed": len(needed),
                      "missing_404": sorted(k for k in needed if cache.get(k) is None),
                      "stats": {str(k): v for k, v in c.stats.items()}}, indent=1))


def discounted(amount_cents, pct):
    # amount * (100 - pct) / 100, rounded half up, in exact integer arithmetic
    num = amount_cents * (100 - pct)
    if num < 0:
        raise ValueError(f"negative discounted amount {amount_cents} @ {pct}%")
    return (num + 50) // 100


def compute(run_dir, out_path):
    orders, dups, conflicts = dedupe(load_listing(run_dir))
    if conflicts:
        raise RuntimeError(f"{len(conflicts)} duplicate listings disagree: {conflicts[:3]}")
    with open(os.path.join(run_dir, "customers.json")) as f:
        customers = json.load(f)
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    q = qualifying(orders)
    for o in q:
        cust = customers[o["customer_id"]]
        if cust is None:
            raise RuntimeError(f"no customer record for {o['id']} ({o['customer_id']})")
        pct = cust["discount_pct"]
        if not (isinstance(pct, int) and not isinstance(pct, bool) and 0 <= pct <= 100):
            raise RuntimeError(f"bad discount_pct {pct!r} for {cust['id']}")
        amt = o["amount_cents"]
        if not (isinstance(amt, int) and not isinstance(amt, bool)):
            raise RuntimeError(f"bad amount_cents {amt!r} on {o['id']}")
        if cust["region"] not in by_region:
            raise RuntimeError(f"unknown region {cust['region']!r} for {cust['id']}")
        by_region[cust["region"]] += discounted(amt, pct)
    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(q),
        "duplicates_skipped": dups,
        "by_region": by_region,
    }
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    import urllib.parse
    cmd, run_dir = sys.argv[1], sys.argv[2]
    os.makedirs(run_dir, exist_ok=True)
    if cmd == "fetch-orders":
        fetch_orders(run_dir)
    elif cmd == "fetch-customers":
        fetch_customers(run_dir)
    elif cmd == "compute":
        compute(run_dir, sys.argv[3])
    else:
        sys.exit(__doc__)

