import sys
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}
CUSTOMER_KEYS = {"id", "name", "region", "tier", "discount_pct"}


class Client:
    def __init__(self, run_dir):
        self.token = None
        self.log = open(os.path.join(run_dir, "events.jsonl"), "a")
        self.stats = Counter()

    def event(self, **kw):
        kw["t"] = time.time()
        self.log.write(json.dumps(kw) + "\n")
        self.log.flush()

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()
        except (urllib.error.URLError, ConnectionError, TimeoutError,
                http.client.HTTPException, OSError) as e:
            return None, None, repr(e).encode()

    @staticmethod
    def _json(body):
        try:
            return json.loads(body)
        except (ValueError, UnicodeDecodeError):
            return None

    @staticmethod
    def _retry_after(headers, data):
        v = headers.get("Retry-After") if headers is not None else None
        if v is not None:
            v = v.strip()
            try:
                return float(v)
            except ValueError:
                when = email.utils.parsedate_to_datetime(v)
                return max(0.0, (when - dt.datetime.now(dt.timezone.utc)).total_seconds())
        if isinstance(data, dict) and isinstance(data.get("retry_after"), (int, float)):
            return float(data["retry_after"])
        return None

    def _handle_failure(self, what, path, status, headers, body, attempt):
        """Log a failed exchange and sleep as appropriate. Returns 'retry' or 'reauth'."""
        data = self._json(body)
        ra = self._retry_after(headers, data)
        self.stats[(what, status)] += 1
        self.event(kind=what, path=path, status=status, retry_after=ra,
                   body=body[:400].decode("utf-8", "replace"))
        if status in (401, 403):
            return "reauth"
        if status == 429:
            if ra is None:
                raise RuntimeError(f"429 without a wait hint on {path}: {body!r}")
            time.sleep(ra)
            return "retry"
        # 5xx, connection errors, anything else transient: honour a hint if given,
        # otherwise back off gently.
        time.sleep(ra if ra is not None else min(0.25 * attempt, 3.0))
        return "retry"

    def refresh_token(self):
        for attempt in range(1, 101):
            status, headers, body = self._raw("POST", "/token", auth=False)
            data = self._json(body)
            if status == 200 and isinstance(data, dict) and isinstance(data.get("token"), str) and data["token"]:
                self.token = data["token"]
                self.stats["tokens_issued"] += 1
                self.event(kind="token", token=self.token)
                return
            if status == 200:  # 200 but unusable body
                status = "bad-200"
            self._handle_failure("token", "/token", status, headers, body, attempt)
        raise RuntimeError("could not obtain a token")

    def get(self, path, validate, allow_404=False, max_attempts=200):
        """GET an authenticated path until a response passes `validate`.

        A 404 is only accepted (returned as None) when allow_404 is set and it
        repeats on several spaced-out attempts, so a transient 404 is not
        mistaken for a missing record."""
        consecutive_404 = 0
        for attempt in range(1, max_attempts + 1):
            if self.token is None:
                self.refresh_token()
            status, headers, body = self._raw("GET", path, auth=True)
            self.stats["requests"] += 1
            if status == 200:
                data = self._json(body)
                problem = validate(data) if data is not None else "invalid JSON"
                if problem is None:
                    return data
                self.stats[("bad-200", path.split("?")[0].rsplit("/", 1)[0])] += 1
                self.event(kind="bad-200", path=path, problem=problem,
                           body=body[:400].decode("utf-8", "replace"))
                time.sleep(min(0.25 * attempt, 3.0))
                continue
            if status == 404 and allow_404:
                consecutive_404 += 1
                self.event(kind="get", path=path, status=404,
                           body=body[:400].decode("utf-8", "replace"))
                if consecutive_404 >= 4:
                    return None
                time.sleep(0.5 * consecutive_404)
                continue
            consecutive_404 = 0
            if self._handle_failure("get", path, status, headers, body, attempt) == "reauth":
                self.token = None
        raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")


def page_validator(expected_page):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = {"page", "total_pages", "items", "next"} - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["page"] != expected_page:
            return f"page field {d['page']!r} != requested {expected_page}"
        if not isinstance(d["items"], list):
            return "items is not a list"
        for it in d["items"]:
            if not isinstance(it, dict) or not ORDER_KEYS <= it.keys():
                return f"malformed item {it!r}"
        return None
    return validate


def customer_validator(cid):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        missing = CUSTOMER_KEYS - d.keys()
        if missing:
            return f"missing keys {sorted(missing)}"
        if d["id"] != cid:
            return f"id {d['id']!r} != requested {cid!r}"
        return None
    return validate


def page_number(path):
    m = re.fullmatch(r"/orders\?page=(\d+)", path)
    return int(m.group(1)) if m else None


def fetch_orders(run_dir):
    c = Client(run_dir)
    pages_dir = os.path.join(run_dir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    path, expected, totals, seq = "/orders?page=1", 1, set(), []
    while path is not None:
        n = page_number(path)
        if n != expected:
            raise RuntimeError(f"next link {path!r} is not page {expected}")
        d = c.get(path, page_validator(n))
        totals.add(d["total_pages"])
        with open(os.path.join(pages_dir, f"page_{n:03d}.json"), "w") as f:
            json.dump(d, f)
        seq.append((n, len(d["items"]), d["next"]))
        path, expected = d["next"], expected + 1
    summary = {
        "pages_fetched": len(seq),
        "total_pages_values": sorted(totals),
        "items_per_page": [s[1] for s in seq],
        "last_next": seq[-1][2],
        "stats": {str(k): v for k, v in c.stats.items()},
    }
    with open(os.path.join(run_dir, "orders_summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps(summary, indent=1))


def load_listing(run_dir):
    pages_dir = os.path.join(run_dir, "pages")
    names = sorted(os.listdir(pages_dir))
    listing = []
    for name in names:
        with open(os.path.join(pages_dir, name)) as f:
            d = json.load(f)
        for it in d["items"]:
            listing.append((d["page"], it))
    return listing


def parse_ts(s):
    t = dt.datetime.fromisoformat(s.replace("Z", "+00:00") if s.endswith("Z") else s)
    if t.tzinfo is None:
        raise ValueError(f"timestamp without offset: {s!r}")
    return t.astimezone(dt.timezone.utc)


START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)  # exclusive


def dedupe(listing):
    """First listing of each id wins; returns (orders, duplicates_skipped, conflicts)."""
    first, dups, conflicts = {}, 0, []
    for page, it in listing:
        if it["id"] in first:
            dups += 1
            if first[it["id"]][1] != it:
                conflicts.append((first[it["id"]], (page, it)))
        else:
            first[it["id"]] = (page, it)
    return {k: v[1] for k, v in first.items()}, dups, conflicts


def qualifying(orders):
    out = []
    for o in orders.values():
        if o["status"] != "shipped":
            continue
        if START <= parse_ts(o["placed_at"]) < END:
            out.append(o)
    return out


def fetch_customers(run_dir):
    orders, _, _ = dedupe(load_listing(run_dir))
    needed = sorted({o["customer_id"] for o in qualifying(orders)})
    cache_path = os.path.join(run_dir, "customers.json")
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path) as f:
            cache = json.load(f)
    c = Client(run_dir)
    for cid in needed:
        if cid in cache:
            continue
        cache[cid] = c.get(f"/customers/{urllib.parse.quote(cid, safe='')}",
                           customer_validator(cid), allow_404=True)
        with open(cache_path, "w") as f:
            json.dump(cache, f, indent=1, sort_keys=True)
    print(json.dumps({"customers_needed": len(needed),
                      "missing_404": sorted(k for k in needed if cache.get(k) is None),
                      "stats": {str(k): v for k, v in c.stats.items()}}, indent=1))


def discounted(amount_cents, pct):
    # amount * (100 - pct) / 100, rounded half up, in exact integer arithmetic
    num = amount_cents * (100 - pct)
    if num < 0:
        raise ValueError(f"negative discounted amount {amount_cents} @ {pct}%")
    return (num + 50) // 100


def compute(run_dir, out_path):
    orders, dups, conflicts = dedupe(load_listing(run_dir))
    if conflicts:
        raise RuntimeError(f"{len(conflicts)} duplicate listings disagree: {conflicts[:3]}")
    with open(os.path.join(run_dir, "customers.json")) as f:
        customers = json.load(f)
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    q = qualifying(orders)
    for o in q:
        cust = customers[o["customer_id"]]
        if cust is None:
            raise RuntimeError(f"no customer record for {o['id']} ({o['customer_id']})")
        pct = cust["discount_pct"]
        if not (isinstance(pct, int) and not isinstance(pct, bool) and 0 <= pct <= 100):
            raise RuntimeError(f"bad discount_pct {pct!r} for {cust['id']}")
        amt = o["amount_cents"]
        if not (isinstance(amt, int) and not isinstance(amt, bool)):
            raise RuntimeError(f"bad amount_cents {amt!r} on {o['id']}")
        if cust["region"] not in by_region:
            raise RuntimeError(f"unknown region {cust['region']!r} for {cust['id']}")
        by_region[cust["region"]] += discounted(amt, pct)
    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(q),
        "duplicates_skipped": dups,
        "by_region": by_region,
    }
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    import urllib.parse
    cmd, run_dir = sys.argv[1], sys.argv[2]
    os.makedirs(run_dir, exist_ok=True)
    if cmd == "fetch-orders":
        fetch_orders(run_dir)
    elif cmd == "fetch-customers":
        fetch_customers(run_dir)
    elif cmd == "compute":
        compute(run_dir, sys.argv[3])
    else:
        sys.exit(__doc__)

